-- «Batafsil» matnlari — Husayn Boyqaro, Gavharshod begim, Behzod va Ali Qushchi.

-- ============================== HUSAYN BOYQARO ==============================

UPDATE fact_cards SET detail_uz = $$Hirotda tug'ilganman; to'liq ismim — Husayn ibn Mirzo Mansur ibn Boyqaro.

